<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\BusinessSetting;use App\Models\ReturnRequest;use App\Models\SupportTicket;use App\Models\User;use App\Services\MarketplaceFinanceService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class ReturnSupportController extends Controller{public function returns(){return view('admin.operations.returns',['returns'=>ReturnRequest::with(['user','resolver','orderItem.order','orderItem.product'])->latest()->paginate(20)]);}public function resolveReturn(Request $r,ReturnRequest $return,MarketplaceFinanceService $finance){abort_if($return->status!=='pending',422,'По этой заявке уже принято решение.');$d=$r->validate(['status'=>['required','in:approved,rejected,refunded'],'resolution'=>['required','string','max:2000'],'refund_amount'=>['nullable','integer','min:0']]);DB::transaction(function()use($return,$d,$r,$finance){$return->update($d+['resolved_by'=>$r->user()->id,'resolved_at'=>now()]);if($d['status']==='refunded'&&($d['refund_amount']??0)>0){$item=$return->orderItem;$order=$item->order;$order->payments()->create(['type'=>'refund','status'=>'refunded','amount'=>$d['refund_amount'],'currency'=>BusinessSetting::current()->currency?:'TMT','note'=>"Возврат по заявке {$return->number}",'processed_at'=>now()]);$refundedTotal=$order->payments()->where('status','refunded')->sum('amount');if($refundedTotal>=$order->total){$order->update(['payment_status'=>'refunded']);}$finance->reverseItem($item,$d['refund_amount'],"Возврат по заявке {$return->number}");}});return back()->with('status','Решение сохранено.');}public function tickets(){return view('admin.operations.tickets',['tickets'=>SupportTicket::with(['user','order'])->withCount('messages')->latest()->paginate(20)]);}public function showTicket(SupportTicket $ticket){$ticket->load(['user','order','assignee','messages.user']);$admins=User::where('role','admin')->orderBy('name')->get(['id','name']);return view('admin.operations.ticket-show',compact('ticket','admins'));}public function replyTicket(Request $r,SupportTicket $ticket){$d=$r->validate(['message'=>['required','string','max:3000']]);$ticket->messages()->create(['user_id'=>$r->user()->id,'message'=>$d['message']]);if($ticket->status==='open'){$ticket->update(['status'=>'in_progress']);}return back()->with('status','Ответ отправлен.');}public function updateTicket(Request $r,SupportTicket $ticket){$d=$r->validate(['status'=>['required',Rule::in(['open','in_progress','answered','closed'])],'priority'=>['required',Rule::in(['low','normal','high','urgent'])],'assigned_to'=>['nullable','exists:users,id']]);$ticket->update($d+['closed_at'=>$d['status']==='closed'?now():null]);return back()->with('status','Тикет обновлён.');} }
